FAQS = [["What is DeepSeek V4 Pro?","DeepSeek V4 Pro is DeepSeek's higher-capability text-only model for long-context reasoning, coding and tool-using agents. The GA version is available via the DeepSeek API using the model ID deepseek-v4-pro."],["Is DeepSeek V4 Pro still available in the API?","Yes. DeepSeek's September 10, 2026 change log says it will continue V4 Pro API service after September 14, reversing the earlier phase-out plan. Always check the official model list for current status."],["What is the DeepSeek V4 Pro model ID?","Use deepseek-v4-pro with the DeepSeek Chat Completions, Responses or supported Anthropic-compatible API. Do not substitute deepseek-flash, which serves V4.1 Flash."],["What is DeepSeek V4 Pro's context window?","The official model registry lists a 1,048,576-token context window, often described as 1M tokens. This is a total context budget, not a promise that every prompt length delivers the same performance."],["What is the maximum DeepSeek V4 Pro output length?","The published maximum is 393,216 tokens (384K). The API's default completion limit is much smaller: 8K without thinking, 64K with thinking, or 128K with max reasoning effort unless max_tokens is set."],["How much does DeepSeek V4 Pro cost per million tokens?","Off-peak rates are $0.66 for uncached input, $0.022 for cache-hit input and $1.98 for output. Peak rates are $1.32 for uncached input, $0.044 for cache-hit input and $3.96 for output, all per million tokens."],["When are DeepSeek V4 Pro peak hours?","Official peak windows are 01:00–04:00 and 06:00–10:00 UTC, Monday through Friday; other hours are off-peak. The catalog also notes Chinese public-holiday exceptions, so check the current provider schedule."],["What reasoning levels does DeepSeek V4 Pro support?","It supports none (thinking disabled), low, high and max. Thinking is enabled by default at high effort. The Chat Completions API uses reasoning_effort and optionally thinking.type."],["Can DeepSeek V4 Pro read images?","No. DeepSeek lists V4 Pro as text-input/text-output only. DeepSeek V4.1 Flash supports image input, so choose Flash if your workflow needs direct visual understanding."],["Does DeepSeek V4 Pro support tools and JSON?","Yes. Its official model table lists tool calls, JSON output, Chat Prefix Completion beta, FIM beta, the Responses API and Anthropic API compatibility. Tool execution is performed by your application, not automatically by the model."],["How does DeepSeek V4 Pro context caching work?","DeepSeek's prefix context caching is enabled by default. When a previously persisted prefix matches, those input tokens are billed at the cache-hit rate. Cache reuse is conditional, not guaranteed for every repeated prompt."],["DeepSeek V4 Pro vs DeepSeek V4.1 Flash: which should I choose?","V4 Pro is the higher-capability text-only option for demanding reasoning, coding and multi-tool tasks; V4.1 Flash is lower-priced, optimized for throughput and supports image input. Both have a 1M-token context window in the official registry."],["Does DeepSeek V4 Pro have published benchmark results?","DeepSeek's August 2026 release supplies named benchmark results for its GA model. SXF also displays independent evaluator results with benchmark names and configurations; do not treat different scores as a single universal quality ranking."],["How do I call DeepSeek V4 Pro using the OpenAI SDK?","Use base_url https://api.deepseek.com, your DeepSeek API key and model deepseek-v4-pro. Choose an optional reasoning_effort such as high, send a messages array and read the final response content and token usage."]]
SECTIONS = "\n        <section class=\"model-deep-section\" id=\"dsv4-overview\" data-deepseek-v4-pro-guide>\n          <div class=\"model-section-head\"><p class=\"eyebrow\">MODEL QUICK ANSWER</p><h2>What is DeepSeek V4 Pro?</h2></div>\n          <p><strong>DeepSeek V4 Pro</strong> is DeepSeek's higher-capability <strong>text-only reasoning, coding and agent model</strong>, released for general availability on August 13, 2026. It offers a <strong>1,048,576-token context window</strong>, a maximum output of <strong>393,216 tokens</strong>, configurable thinking effort, tool calling and compatible Chat Completions / Responses / Anthropic-style APIs. The exact model ID is <code>deepseek-v4-pro</code>.</p>\n          <p>The key distinction from <a href=\"/models/deepseek-v4-1-flash/\">DeepSeek V4.1 Flash</a> is model positioning: V4 Pro prioritizes difficult text reasoning and coding; Flash emphasizes throughput, lower API cost and image input. DeepSeek's pricing uses <strong>peak and off-peak rates</strong>, with much cheaper cached-input tokens. It is not accurate to display one permanent flat token price.</p>\n          <nav class=\"model-related-links\" aria-label=\"DeepSeek V4 Pro reference sections\">\n            <a href=\"#dsv4-pricing\"><span>OFFICIAL API COSTS</span><strong>Peak, off-peak and cache rates</strong><b>↗</b></a>\n            <a href=\"#dsv4-api\"><span>API EXAMPLE</span><strong>Call V4 Pro with reasoning</strong><b>↗</b></a>\n            <a href=\"#dsv4-comparison\"><span>MODEL COMPARISON</span><strong>DeepSeek V4 Pro vs Flash</strong><b>↗</b></a>\n          </nav>\n        </section>\n\n        <section class=\"model-deep-section\" id=\"dsv4-specs\">\n          <div class=\"model-section-head\"><p class=\"eyebrow\">VERIFIED SPECIFICATIONS</p><h2>DeepSeek V4 Pro context window, max output and API capabilities.</h2></div>\n          <div class=\"model-capability-grid\">\n            <article><span>MODEL IDENTIFIER</span><h3><code>deepseek-v4-pro</code></h3><p>The current official DeepSeek API ID. The provider lists its model version as DeepSeek-V4-Pro-0813.</p></article>\n            <article><span>CONTEXT WINDOW</span><h3>1,048,576 tokens (1M)</h3><p>Shared input/conversation context capacity. Treat long-context accuracy as a workload-specific benchmark question, not a guaranteed perfect recall claim.</p></article>\n            <article><span>MAXIMUM OUTPUT</span><h3>393,216 tokens (384K)</h3><p>Hard API ceiling; defaults are 8K non-thinking, 64K thinking, 128K with max effort. Configure <code>max_tokens</code> and watch the total context budget.</p></article>\n            <article><span>REASONING EFFORT</span><h3>none · low · high · max</h3><p>Thinking is enabled by default at <code>high</code>; <code>none</code> disables it. Low suits simpler tasks, while max is available for difficult reasoning workflows.</p></article>\n            <article><span>INPUT AND OUTPUT</span><h3>Text → text</h3><p>Official DeepSeek V4 Pro does not support vision input. Do not assume image-capable features from the V4.1 Flash model carry over.</p></article>\n            <article><span>DEVELOPER FEATURES</span><h3>Tools · JSON · Responses</h3><p>DeepSeek lists function calling, JSON output, Responses and Anthropic APIs, chat-prefix completion beta and fill-in-the-middle completion beta.</p></article>\n          </div>\n          <p>Sources: <a href=\"https://api-docs.deepseek.com/quick_start/pricing/\" target=\"_blank\" rel=\"noopener noreferrer\">DeepSeek model and price table</a>, <a href=\"https://api-docs.deepseek.com/api/list-models/\" target=\"_blank\" rel=\"noopener noreferrer\">model registry</a> and <a href=\"https://api-docs.deepseek.com/api/create-chat-completion/\" target=\"_blank\" rel=\"noopener noreferrer\">Chat Completions request limits</a>. The catalog does not publish a verified knowledge-cutoff date, so none is invented here.</p>\n        </section>\n\n        <section class=\"model-deep-section\" id=\"dsv4-pricing\">\n          <div class=\"model-section-head\"><p class=\"eyebrow\">DEEPSEEK API PRICING</p><h2>DeepSeek V4 Pro pricing: peak vs off-peak and cache hits.</h2></div>\n          <p>DeepSeek charges for <strong>uncached input tokens, cached input tokens and generated output tokens</strong>. All six figures below are in <strong>USD per one million tokens</strong>. Prices are time-dependent and the provider can update them; do not use a fixed-price calculator that ignores UTC billing windows.</p>\n          <div class=\"model-capability-grid\">\n            <article><span>OFF-PEAK INPUT · CACHE MISS</span><h3>$0.66 / 1M</h3><p>Uncached text input during off-peak hours. Used for fresh prompts or nonmatching cached prefixes.</p></article>\n            <article><span>OFF-PEAK INPUT · CACHE HIT</span><h3>$0.022 / 1M</h3><p>Charged only when DeepSeek's cache actually reuses a persisted prompt prefix.</p></article>\n            <article><span>OFF-PEAK OUTPUT</span><h3>$1.98 / 1M</h3><p>Generated output tokens. Include any billed reasoning output in your overall usage estimates.</p></article>\n            <article><span>PEAK INPUT · CACHE MISS</span><h3>$1.32 / 1M</h3><p>New input during peak hours; double the off-peak uncached rate.</p></article>\n            <article><span>PEAK INPUT · CACHE HIT</span><h3>$0.044 / 1M</h3><p>Cached-prefix input during peak hours, when the cache-hit condition is met.</p></article>\n            <article><span>PEAK OUTPUT</span><h3>$3.96 / 1M</h3><p>Generated output during peak hours; double the off-peak output rate.</p></article>\n          </div>\n          <p><strong>Peak times:</strong> 01:00–04:00 UTC and 06:00–10:00 UTC, Monday through Friday. Other times are off-peak; check DeepSeek's current holiday exceptions and service notice. Off-peak token prices are one-half of peak prices across all three billing dimensions.</p>\n          <p><strong>Concrete cost example:</strong> a request with 100,000 uncached input tokens and 20,000 output tokens is approximately <strong>$0.1056 off-peak</strong> (0.1 × $0.66 + 0.02 × $1.98), or <strong>$0.2112 at peak</strong> (0.1 × $1.32 + 0.02 × $3.96). If all 100,000 input tokens qualify as cache hits, the corresponding off-peak estimate is <strong>$0.0418</strong>. These are arithmetic examples, not a fixed price for every request or a latency guarantee.</p>\n          <p>See the <a href=\"https://api-docs.deepseek.com/quick_start/pricing/\" target=\"_blank\" rel=\"noopener noreferrer\">official DeepSeek token rate card</a>. SXF intentionally excludes this model from its flat-price calculator because a single input/output pair would misstate real billing.</p>\n        </section>\n\n        <section class=\"model-deep-section\" id=\"dsv4-reasoning\">\n          <div class=\"model-section-head\"><p class=\"eyebrow\">THINKING AND REASONING</p><h2>DeepSeek V4 Pro thinking mode: none, low, high and max.</h2></div>\n          <p>DeepSeek supports non-thinking and thinking modes. Thinking is on by default, with <code>high</code> effort. Developers can choose <code>reasoning_effort: \"none\"</code>, <code>\"low\"</code>, <code>\"high\"</code> or <code>\"max\"</code>. The provider maps compatibility aliases such as <code>medium</code> to high, so a label does not necessarily represent a distinct compute tier.</p>\n          <div class=\"model-capability-grid\">\n            <article><span>NONE</span><h3>Thinking disabled</h3><p>Use for straightforward extraction, summarization or formatting where additional deliberation is unnecessary.</p></article>\n            <article><span>LOW</span><h3>Light deliberation</h3><p>Consider for simple coding corrections, routine instructions or agent steps where throughput matters.</p></article>\n            <article><span>HIGH</span><h3>Default effort</h3><p>Balances more deliberate text reasoning with normal agent workflows. Evaluate token usage and answer quality on your own tasks.</p></article>\n            <article><span>MAX</span><h3>Deepest supported tier</h3><p>Use selectively for challenging repository analysis, mathematics or multi-step reasoning. It can increase billed output and latency.</p></article>\n          </div>\n          <p><strong>Important parameter behavior:</strong> in thinking mode, DeepSeek documents that <code>temperature</code>, <code>presence_penalty</code> and <code>frequency_penalty</code> do not take effect. <code>top_p</code> is constrained to 0.95–1.0. For tool-using conversations, handling of <code>reasoning_content</code> differs from ordinary text-only multi-turn chats; follow the provider's <a href=\"https://api-docs.deepseek.com/guides/thinking_mode/\" target=\"_blank\" rel=\"noopener noreferrer\">thinking-mode state guidance</a>.</p>\n        </section>\n\n        <section class=\"model-deep-section\" id=\"dsv4-api\">\n          <div class=\"model-section-head\"><p class=\"eyebrow\">API QUICKSTART</p><h2>How to call the DeepSeek V4 Pro API.</h2></div>\n          <p>The provider uses the OpenAI-compatible base URL <code>https://api.deepseek.com</code>. Send a <code>POST /chat/completions</code> request with a DeepSeek API key, the exact <code>deepseek-v4-pro</code> identifier and an appropriate <code>reasoning_effort</code>. The following is a minimal text-only call; keep API keys on the server.</p>\n          <pre style=\"white-space:pre-wrap;overflow-wrap:anywhere;overflow-x:auto\"><code>curl https://api.deepseek.com/chat/completions \\\n  -H \"Authorization: Bearer $DEEPSEEK_API_KEY\" \\\n  -H \"Content-Type: application/json\" \\\n  -d '{\n    \"model\": \"deepseek-v4-pro\",\n    \"messages\": [\n      {\"role\": \"system\", \"content\": \"Give concise, verifiable answers.\"},\n      {\"role\": \"user\", \"content\": \"Explain three trade-offs in a database migration plan.\"}\n    ],\n    \"reasoning_effort\": \"high\",\n    \"thinking\": {\"type\": \"enabled\"},\n    \"max_tokens\": 2048\n  }'</code></pre>\n          <div class=\"model-caveat-list\">\n            <div><span>01</span><p><strong>Call the correct model:</strong> use <code>deepseek-v4-pro</code>. <code>deepseek-flash</code> points to the separate V4.1 Flash model and its own price schedule.</p></div>\n            <div><span>02</span><p><strong>Control reasoning:</strong> use <code>reasoning_effort</code> to choose low, high or max; set <code>thinking.type</code> if an explicit enabled/disabled toggle is useful in your client.</p></div>\n            <div><span>03</span><p><strong>Budget output:</strong> set <code>max_tokens</code> within the documented 384K ceiling, and inspect <code>finish_reason</code> if an output gets truncated.</p></div>\n            <div><span>04</span><p><strong>Capture real cost:</strong> inspect <code>usage</code> and its <code>prompt_cache_hit_tokens</code> / <code>prompt_cache_miss_tokens</code> breakdown, and apply the billing window in UTC.</p></div>\n          </div>\n          <p>DeepSeek also provides <a href=\"https://api-docs.deepseek.com/api/create-response/\" target=\"_blank\" rel=\"noopener noreferrer\">OpenAI Responses API compatibility</a> and an <a href=\"https://api-docs.deepseek.com/\" target=\"_blank\" rel=\"noopener noreferrer\">OpenAI/Anthropic SDK quickstart</a>. Validate current parameter support in the endpoint you actually call.</p>\n        </section>\n\n        <section class=\"model-deep-section\" id=\"dsv4-tool-use\">\n          <div class=\"model-section-head\"><p class=\"eyebrow\">AGENT AND CODING WORKFLOWS</p><h2>DeepSeek V4 Pro tool calling, JSON output and coding agents.</h2></div>\n          <div class=\"model-capability-grid\">\n            <article><span>FUNCTION CALLING</span><h3>Agent tools and external APIs</h3><p>The model can emit structured function-call requests for your application to execute. Tools are not executed magically by the model; validate arguments and permissions before invoking them.</p></article>\n            <article><span>JSON OUTPUT</span><h3>Machine-readable text</h3><p>Set <code>response_format: {\"type\":\"json_object\"}</code> and explicitly ask for JSON in the prompt. Check truncation and parsing before using generated data downstream.</p></article>\n            <article><span>REPOSITORY CODING</span><h3>Long-context code analysis</h3><p>Use the large context budget to include repository specifications or logs. Actual performance depends on retrieval quality, prompt construction and evaluation, not token capacity alone.</p></article>\n            <article><span>RESPONSES API</span><h3>Multi-step agent messages</h3><p>DeepSeek supports the Responses API format, with model-produced tool calls and application-supplied tool results; its documented endpoint is stateless.</p></article>\n          </div>\n          <p><strong>Conversation state matters:</strong> when tool calls are present, DeepSeek's thinking documentation describes how to carry forward previous <code>reasoning_content</code> where required. For mid-conversation insertion of tool calls, its documentation advises Responses or Anthropic API rather than Chat Completions. See <a href=\"https://api-docs.deepseek.com/guides/tool_calls/\" target=\"_blank\" rel=\"noopener noreferrer\">Tool Calls</a> and <a href=\"https://api-docs.deepseek.com/guides/json_mode/\" target=\"_blank\" rel=\"noopener noreferrer\">JSON Output</a>.</p>\n        </section>\n\n        <section class=\"model-deep-section\" id=\"dsv4-cache\">\n          <div class=\"model-section-head\"><p class=\"eyebrow\">CACHING AND COST CONTROL</p><h2>How DeepSeek V4 Pro context caching reduces input cost.</h2></div>\n          <p>DeepSeek enables <strong>prefix-based context caching by default</strong>. When a previous prompt prefix has been persisted and the next request matches it, qualifying input tokens use the <strong>cache-hit rate</strong> instead of the uncached input price. A shared system prompt or stable document prefix is a candidate for reuse, but cache hits are not guaranteed.</p>\n          <div class=\"model-caveat-list\">\n            <div><span>01</span><p><strong>Put reusable context first:</strong> keep stable system instructions and shared documents at the beginning of repeated requests, where matching is possible.</p></div>\n            <div><span>02</span><p><strong>Inspect reported cache usage:</strong> compare <code>prompt_cache_hit_tokens</code> with <code>prompt_cache_miss_tokens</code> to see how much reuse occurred.</p></div>\n            <div><span>03</span><p><strong>Separate cache from schedule:</strong> off-peak cache hits cost $0.022 per million tokens; peak cache hits cost $0.044 per million. Peak/off-peak is a separate multiplier.</p></div>\n            <div><span>04</span><p><strong>Measure production behavior:</strong> changing prefixes, cache persistence and workload patterns can reduce hit rates. Do not treat maximum theoretical savings as an observed benchmark.</p></div>\n          </div>\n          <p>Reference: <a href=\"https://api-docs.deepseek.com/guides/kv_cache/\" target=\"_blank\" rel=\"noopener noreferrer\">DeepSeek context caching documentation</a>.</p>\n        </section>\n\n        <section class=\"model-deep-section\" id=\"dsv4-comparison\">\n          <div class=\"model-section-head\"><p class=\"eyebrow\">MODEL COMPARISON</p><h2>DeepSeek V4 Pro vs V4.1 Flash: cost, vision and context.</h2></div>\n          <div class=\"model-capability-grid\">\n            <article><span>HIGHER-CAPABILITY TEXT MODEL</span><h3>DeepSeek V4 Pro</h3><p>Official version DeepSeek-V4-Pro-0813. Text input and output; 1M context; 384K output; off-peak uncached input $0.66/1M and output $1.98/1M. Best evaluated on difficult text reasoning, code and agents.</p></article>\n            <article><span>LOWER-COST MULTIMODAL</span><h3><a href=\"/models/deepseek-v4-1-flash/\">DeepSeek V4.1 Flash</a></h3><p>Official API ID <code>deepseek-flash</code>. Supports image input (not image generation), with the same listed 1M context / 384K max output. Off-peak uncached input $0.15/1M and output $0.60/1M.</p></article>\n          </div>\n          <p><strong>Practical choice:</strong> use V4 Pro when sophisticated reasoning or long multi-tool workflows justify a higher token budget. Choose V4.1 Flash for image questions, inexpensive high-volume workloads or routine agent requests. Both need evaluation on your own data; this comparison does not claim a universal quality winner.</p>\n          <p>DeepSeek's <a href=\"https://api-docs.deepseek.com/quick_start/pricing/\" target=\"_blank\" rel=\"noopener noreferrer\">official side-by-side feature table</a> is the source for capabilities and prices. For other providers, explore the <a href=\"/compare/\">SXF comparison hub</a> or the <a href=\"/models/pricing/\">model pricing index</a>.</p>\n        </section>\n\n        <section class=\"model-deep-section\" id=\"dsv4-benchmarks\">\n          <div class=\"model-section-head\"><p class=\"eyebrow\">EVALUATION CONTEXT</p><h2>How to interpret DeepSeek V4 Pro benchmarks.</h2></div>\n          <p>DeepSeek's August 2026 V4 Pro general-availability announcement reports improvements in agent and developer tests, including named tasks such as Terminal Bench, NL2Repo, DeepSWE and Toolathlon. Provider-reported evaluations are useful evidence, but they are not the same as independent results or proof of performance on every software project.</p>\n          <p>SXF's existing <a href=\"/evaluations/\">model evaluation evidence</a> section includes independent Artificial Analysis observations with benchmark versions and reasoning settings. Always keep <strong>the evaluator, date, task and effort level</strong> attached to a numerical score; do not blend scores from different methods into a single invented ranking. <a href=\"https://api-docs.deepseek.com/news/news260813/\" target=\"_blank\" rel=\"noopener noreferrer\">Official GA announcement</a>.</p>\n        </section>\n\n        <section class=\"model-deep-section\" id=\"dsv4-limitations\">\n          <div class=\"model-section-head\"><p class=\"eyebrow\">REAL-WORLD USE CASES</p><h2>When to use DeepSeek V4 Pro — and what it cannot do.</h2></div>\n          <div class=\"model-capability-grid\">\n            <article><span>COMPLEX CODING</span><h3>Repository-level problem solving</h3><p>Review migration plans, debug cross-file behavior and reason about implementation trade-offs. Pair responses with tests and security review.</p></article>\n            <article><span>DOCUMENT REASONING</span><h3>Large text collections</h3><p>Analyze extensive text or structured logs while retaining broad context. Verify citations and facts against the original source documents.</p></article>\n            <article><span>AGENT WORKFLOWS</span><h3>Orchestrating several tools</h3><p>Plan multi-step tasks and request structured tools. Keep external action execution, authorization and validation inside the application.</p></article>\n            <article><span>LIMITATIONS</span><h3>No native image input</h3><p>Do not send screenshots expecting V4 Pro to inspect pixels. Use <a href=\"/models/deepseek-v4-1-flash/\">DeepSeek V4.1 Flash</a> for vision tasks, and review usage caps and billing windows for production.</p></article>\n          </div>\n          <p>DeepSeek has not published a verified knowledge cutoff for this model in SXF's evidence ledger. The existence of a large context window does not establish web browsing, perfect recall, guaranteed fact accuracy or access to private systems without the tools your application supplies.</p>\n        </section>\n\n        <section class=\"model-deep-section\" id=\"dsv4-related\">\n          <div class=\"model-section-head\"><p class=\"eyebrow\">INTERNAL MODEL DISCOVERY</p><h2>Related DeepSeek models, pricing and developer research.</h2></div>\n          <div class=\"model-related-links\">\n            <a href=\"/models/deepseek-v4-1-flash/\"><span>CHEAPER ALTERNATIVE</span><strong>DeepSeek V4.1 Flash specs and pricing</strong><b>↗</b></a>\n            <a href=\"/providers/deepseek/\"><span>MODEL PROVIDER</span><strong>DeepSeek model portfolio</strong><b>↗</b></a>\n            <a href=\"/models/pricing/\"><span>COMPARE API ECONOMICS</span><strong>Verified model pricing and billing</strong><b>↗</b></a>\n            <a href=\"/compare/\"><span>EXPLORE OTHER MODELS</span><strong>SXF model comparison hub</strong><b>↗</b></a>\n            <a href=\"/evaluations/\"><span>INDEPENDENT RESULTS</span><strong>Model evaluation evidence</strong><b>↗</b></a>\n            <a href=\"/models/\"><span>MODEL DIRECTORY</span><strong>All AI model references</strong><b>↗</b></a>\n          </div>\n        </section>\n"
FAQ_HTML = "\n        <section class=\"model-deep-section\" id=\"dsv4-faq\">\n          <div class=\"model-section-head\"><p class=\"eyebrow\">DEEPSEEK V4 PRO FAQ</p><h2>Frequently asked questions about API access, reasoning and pricing.</h2></div>\n          <div class=\"model-caveat-list\">\n            <div><span>01</span><p><strong>What is DeepSeek V4 Pro?</strong> DeepSeek V4 Pro is DeepSeek's higher-capability text-only model for long-context reasoning, coding and tool-using agents. The GA version is available via the DeepSeek API using the model ID deepseek-v4-pro.</p></div>\n            <div><span>02</span><p><strong>Is DeepSeek V4 Pro still available in the API?</strong> Yes. DeepSeek's September 10, 2026 change log says it will continue V4 Pro API service after September 14, reversing the earlier phase-out plan. Always check the official model list for current status.</p></div>\n            <div><span>03</span><p><strong>What is the DeepSeek V4 Pro model ID?</strong> Use deepseek-v4-pro with the DeepSeek Chat Completions, Responses or supported Anthropic-compatible API. Do not substitute deepseek-flash, which serves V4.1 Flash.</p></div>\n            <div><span>04</span><p><strong>What is DeepSeek V4 Pro's context window?</strong> The official model registry lists a 1,048,576-token context window, often described as 1M tokens. This is a total context budget, not a promise that every prompt length delivers the same performance.</p></div>\n            <div><span>05</span><p><strong>What is the maximum DeepSeek V4 Pro output length?</strong> The published maximum is 393,216 tokens (384K). The API's default completion limit is much smaller: 8K without thinking, 64K with thinking, or 128K with max reasoning effort unless max_tokens is set.</p></div>\n            <div><span>06</span><p><strong>How much does DeepSeek V4 Pro cost per million tokens?</strong> Off-peak rates are $0.66 for uncached input, $0.022 for cache-hit input and $1.98 for output. Peak rates are $1.32 for uncached input, $0.044 for cache-hit input and $3.96 for output, all per million tokens.</p></div>\n            <div><span>07</span><p><strong>When are DeepSeek V4 Pro peak hours?</strong> Official peak windows are 01:00–04:00 and 06:00–10:00 UTC, Monday through Friday; other hours are off-peak. The catalog also notes Chinese public-holiday exceptions, so check the current provider schedule.</p></div>\n            <div><span>08</span><p><strong>What reasoning levels does DeepSeek V4 Pro support?</strong> It supports none (thinking disabled), low, high and max. Thinking is enabled by default at high effort. The Chat Completions API uses reasoning_effort and optionally thinking.type.</p></div>\n            <div><span>09</span><p><strong>Can DeepSeek V4 Pro read images?</strong> No. DeepSeek lists V4 Pro as text-input/text-output only. DeepSeek V4.1 Flash supports image input, so choose Flash if your workflow needs direct visual understanding.</p></div>\n            <div><span>10</span><p><strong>Does DeepSeek V4 Pro support tools and JSON?</strong> Yes. Its official model table lists tool calls, JSON output, Chat Prefix Completion beta, FIM beta, the Responses API and Anthropic API compatibility. Tool execution is performed by your application, not automatically by the model.</p></div>\n            <div><span>11</span><p><strong>How does DeepSeek V4 Pro context caching work?</strong> DeepSeek's prefix context caching is enabled by default. When a previously persisted prefix matches, those input tokens are billed at the cache-hit rate. Cache reuse is conditional, not guaranteed for every repeated prompt.</p></div>\n            <div><span>12</span><p><strong>DeepSeek V4 Pro vs DeepSeek V4.1 Flash: which should I choose?</strong> V4 Pro is the higher-capability text-only option for demanding reasoning, coding and multi-tool tasks; V4.1 Flash is lower-priced, optimized for throughput and supports image input. Both have a 1M-token context window in the official registry.</p></div>\n            <div><span>13</span><p><strong>Does DeepSeek V4 Pro have published benchmark results?</strong> DeepSeek's August 2026 release supplies named benchmark results for its GA model. SXF also displays independent evaluator results with benchmark names and configurations; do not treat different scores as a single universal quality ranking.</p></div>\n            <div><span>14</span><p><strong>How do I call DeepSeek V4 Pro using the OpenAI SDK?</strong> Use base_url https://api.deepseek.com, your DeepSeek API key and model deepseek-v4-pro. Choose an optional reasoning_effort such as high, send a messages array and read the final response content and token usage.</p></div>\n          </div>\n        </section>\n"
SOURCES = ["https://api-docs.deepseek.com/quick_start/pricing/","https://api-docs.deepseek.com/api/list-models/","https://api-docs.deepseek.com/guides/thinking_mode/","https://api-docs.deepseek.com/api/create-chat-completion/","https://api-docs.deepseek.com/guides/tool_calls/","https://api-docs.deepseek.com/guides/kv_cache/","https://api-docs.deepseek.com/updates/","https://api-docs.deepseek.com/api/create-response/"]

_CAVEATS = '<section class="model-deep-section"><div class="model-section-head"><p class="eyebrow">CAVEATS</p>'


def _once(page: str, old: str, replacement: str) -> str:
    if page.count(old) != 1:
        raise ValueError("DeepSeek V4 Pro page generator contract changed: " + old[:75])
    return page.replace(old, replacement, 1)


def _replace_meta(page: str, name: str, value: str) -> str:
    pattern = r'(<meta (?:name|property)="' + re.escape(name) + r'" content=")[^"]*(" />)'
    page, count = re.subn(
        pattern,
        lambda m: m.group(1) + escape(value, quote=True) + m.group(2),
        page,
        count=1,
    )
    if count != 1:
        raise ValueError("DeepSeek V4 Pro expected metadata missing: " + name)
    return page


def enrich_deepseek_v4_pro_page(page: str) -> str:
    """Add useful specialist model content without touching its canonical URL."""
    if 'data-deepseek-v4-pro-guide' in page:
        return page
    if f'<link rel="canonical" href="{CANONICAL}"' not in page:
        raise ValueError("DeepSeek V4 Pro canonical URL drift")
    page, count = re.subn(r"<title>.*?</title>", "<title>" + escape(TITLE) + "</title>", page, count=1)
    if count != 1:
        raise ValueError("DeepSeek V4 Pro HTML title missing")
    for key, value in (
        ("description", DESCRIPTION),
        ("og:title", TITLE),
        ("og:description", DESCRIPTION),
        ("twitter:title", TITLE),
        ("twitter:description", DESCRIPTION),
    ):
        page = _replace_meta(page, key, value)

    for old, replacement in (
        (
            '<h1>DeepSeek V4 Pro<br><span>verified model reference.</span></h1>',
            '<h1>DeepSeek V4 Pro<br><span>API pricing, 1M context &amp; reasoning.</span></h1>',
        ),
        (
            '<p>DeepSeek&#x27;s higher-capability V4 API model for long-context reasoning, coding and agentic text workloads.</p>',
            '<p>' + escape(HERO) + '</p>',
        ),
        (
            '<div><span>STANDARD RATE</span><strong>Not published</strong><small>per 1 million tokens</small></div>',
            '<div><span>OFF-PEAK INPUT</span><strong>$0.66</strong><small>per million uncached tokens; peak $1.32</small></div>',
        ),
        (
            '<div><span>OUTPUT RATE</span><strong>—</strong><small>per 1 million tokens</small></div>',
            '<div><span>OFF-PEAK OUTPUT</span><strong>$1.98</strong><small>per million tokens; peak $3.96</small></div>',
        ),
        (
            '<article><span>REASONING</span><h3>none · low · high · max · default high</h3><p>Only provider-documented reasoning controls are shown; missing controls remain unpublished rather than inferred.</p></article>',
            '<article><span>REASONING EFFORT</span><h3>none · low · high · max</h3><p>Thinking is enabled by default at high. See the API controls and practical reasoning trade-offs below.</p></article>',
        ),
        (
            '<div><p>Official paid API.</p><p>SXF preserves the provider-published native billing basis. Only calculator-eligible generative token models enter token-cost arithmetic; specialist units and input-only embeddings remain visible without forced conversion.</p></div>',
            '<div><p>Off-peak per million tokens: $0.66 uncached input, $0.022 cached input and $1.98 output. Peak: $1.32, $0.044 and $3.96 respectively.</p><p>Pricing is time-variable, so SXF does not force V4 Pro into a misleading fixed-rate calculator. See exact UTC hours and cost examples below.</p></div>',
        ),
    ):
        page = _once(page, old, replacement)

    match = re.search(r'(<script type="application/ld\+json">)(.*?)(</script>)', page, re.DOTALL)
    if match is None:
        raise ValueError("DeepSeek V4 Pro JSON-LD script missing")
    schema = json.loads(match.group(2))
    graph = schema.get("@graph", [])
    article = next((node for node in graph if node.get("@type") == "TechArticle"), None)
    crumb = next((node for node in graph if node.get("@type") == "BreadcrumbList"), None)
    if article is None or crumb is None:
        raise ValueError("DeepSeek V4 Pro article/breadcrumb schema contract changed")
    article.update({
        "headline": TITLE.removesuffix(" | SXF / AI"),
        "description": DESCRIPTION,
        "citation": SOURCES,
        "mainEntityOfPage": {"@id": CANONICAL},
        "author": {"@id": "https://sxf.si/#organization"},
        "publisher": {"@id": "https://sxf.si/#organization"},
        "about": {
            "@type": "Thing",
            "name": "DeepSeek V4 Pro",
            "alternateName": "DeepSeek-V4-Pro-0813",
            "identifier": "deepseek-v4-pro",
            "sameAs": SOURCES[1],
        },
        "keywords": [
            "DeepSeek V4 Pro", "DeepSeek V4 Pro API",
            "DeepSeek V4 Pro pricing", "DeepSeek V4 Pro context window",
            "DeepSeek V4 Pro vs Flash", "DeepSeek V4 Pro thinking mode",
        ],
        "mentions": [
            {"@type": "Thing", "name": "DeepSeek V4.1 Flash", "url": "https://sxf.si/models/deepseek-v4-1-flash/"},
        ],
    })
    crumb["@id"] = CANONICAL + "#breadcrumb"
    graph.insert(0, {
        "@type": "WebPage",
        "@id": CANONICAL,
        "url": CANONICAL,
        "name": TITLE.removesuffix(" | SXF / AI"),
        "description": DESCRIPTION,
        "inLanguage": "en",
        "mainEntity": {"@id": CANONICAL + "#article"},
        "breadcrumb": {"@id": CANONICAL + "#breadcrumb"},
        "isPartOf": {"@id": "https://sxf.si/#website"},
    })
    graph.append({
        "@type": "WebSite",
        "@id": "https://sxf.si/#website",
        "name": "SXF / AI",
        "url": "https://sxf.si/",
        "publisher": {"@id": "https://sxf.si/#organization"},
    })
    graph.append({
        "@type": "Organization",
        "@id": "https://sxf.si/#organization",
        "name": "SXF / AI",
        "url": "https://sxf.si/",
    })
    graph.append({
        "@type": "FAQPage",
        "@id": CANONICAL + "#faq",
        "url": CANONICAL + "#dsv4-faq",
        "inLanguage": "en",
        "mainEntity": [
            {"@type": "Question", "name": q, "acceptedAnswer": {"@type": "Answer", "text": a}}
            for q, a in FAQS
        ],
    })
    new_jsonld = json.dumps(schema, ensure_ascii=False, separators=(",", ":"))
    page = page[:match.start(2)] + new_jsonld + page[match.end(2):]
    return _once(page, _CAVEATS, SECTIONS + FAQ_HTML + "\n\n        " + _CAVEATS)
